#[derive(Debug, Clone)]
pub struct BroadcastObject {
    // The shape of the broadcast grid: (rows, columns)
    shape: (usize, usize),
    // Underlying data from the first and second arrays
    xs: Vec<f32>,
    ys: Vec<f32>,
}

impl BroadcastObject {
    /// Returns the shape of the broadcast grid as (len(xs), len(ys)).
    pub fn shape(&self) -> (usize, usize) {
        self.shape
    }

    /// Returns the pair (xs[i], ys[j]) for 0 <= i < shape.0, 0 <= j < shape.1.
    /// Panics if `i` or `j` is out of bounds.
    pub fn get(&self, i: usize, j: usize) -> (f32, f32) {
        (self.xs[i], self.ys[j])
    }
}

/// Constructs a broadcast object representing the Cartesian product
/// of `x` and `y`.  The resulting object will have shape
/// `(x.len(), y.len())`, and `get(i, j)` returns `(x[i], y[j])`.
pub fn broadcast(x: Vec<f32>, y: Vec<f32>) -> BroadcastObject {
    let shape = (x.len(), y.len());
    BroadcastObject { shape, xs: x, ys: y }
}

